if os.path.exists(dist):
    for item in os.listdir(dist):
        item_path = os.path.join(dist, item)
        if os.path.isdir(item_path):
            shutil.rmtree(item_path)
        else:
            os.remove(item_path)
    print('dist cleaned')
else:
